import { test, expect } from '@playwright/test';

test.describe('Modal Dialog - Focus Management on Close', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-dialog');
  });

  test('should move focus back to trigger button when modal closes via close button', async ({ page }) => {
    // Open modal by clicking trigger button
    const triggerButton = page.getByRole('button', { name: /open modal/i });
    await triggerButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify focus is on modal trigger button
    await expect(triggerButton).toBeFocused();

    // Close modal using close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify focus is returned to trigger button
    await expect(triggerButton).toBeFocused();
  });

  test('should move focus back to trigger button when modal closes via escape key', async ({ page }) => {
    // Open modal by clicking trigger button
    const triggerButton = page.getByRole('button', { name: /open modal/i });
    await triggerButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify focus is on modal trigger button
    await expect(triggerButton).toBeFocused();

    // Close modal using escape key
    await page.keyboard.press('Escape');

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify focus is returned to trigger button
    await expect(triggerButton).toBeFocused();
  });
});
